// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// 保存单条可关闭公告横幅
	// (PUT /v1/banner)
	UpdateBanner(w http.ResponseWriter, r *http.Request)
	// 取得可恢复的数据屏障
	// (POST /v1/barriers)
	AcquireBarrier(w http.ResponseWriter, r *http.Request)
	// 释放屏障
	// (DELETE /v1/barriers/{barrierId})
	ReleaseBarrier(w http.ResponseWriter, r *http.Request, barrierId Identifier)
	// 更新站名/logo/图标/主题色/默认分享图
	// (PUT /v1/branding)
	UpdateBranding(w http.ResponseWriter, r *http.Request)
	// 读取后台站点配置
	// (GET /v1/config)
	ReadSiteConfig(w http.ResponseWriter, r *http.Request)
	// 更新站点常规配置
	// (PUT /v1/config)
	UpdateSiteConfig(w http.ResponseWriter, r *http.Request)
	// 站点设置历史
	// (GET /v1/config/history)
	ReadConfigHistory(w http.ResponseWriter, r *http.Request, params ReadConfigHistoryParams)
	// 回滚站点设置
	// (POST /v1/config/history/{revisionId}:restore)
	RestoreConfigRevision(w http.ResponseWriter, r *http.Request, revisionId Identifier)
	// 更新页脚版权/自定义链接/ICP备案/源码链接
	// (PUT /v1/footer)
	UpdateFooter(w http.ResponseWriter, r *http.Request)
	// 配置首页介绍、卡片和精选文档
	// (PUT /v1/home)
	UpdateHome(w http.ResponseWriter, r *http.Request)
	// 读取可公开的首页配置
	// (GET /v1/home/public)
	ReadPublicHome(w http.ResponseWriter, r *http.Request, params ReadPublicHomeParams)
	// 读取安全初始化阶段
	// (GET /v1/initialization)
	ReadInitializationStatus(w http.ResponseWriter, r *http.Request)
	// 无需AI完成首站点初始化
	// (POST /v1/initialization)
	InitializeSite(w http.ResponseWriter, r *http.Request)
	// 取消尚未持久commit的初始化
	// (POST /v1/initialization:abort)
	AbortInitialization(w http.ResponseWriter, r *http.Request)
	// 恢复崩溃或依赖断开的初始化阶段
	// (POST /v1/initialization:resume)
	ResumeInitialization(w http.ResponseWriter, r *http.Request)
	// 读取已提交的本域不可变对象原始字节
	// (GET /v1/objects/{objectId})
	ReadConfigObject(w http.ResponseWriter, r *http.Request, objectId Identifier, params ReadConfigObjectParams)
	// 媒体核对首页资源来源持久决定
	// (GET /v1/reference-decisions/{sourceOperationId})
	ReadHomeReferenceDecision(w http.ResponseWriter, r *http.Request, sourceOperationId TypesIdentifier)
	// 站点设置完整资源引用
	// (GET /v1/resource-references)
	ListResourceReferences(w http.ResponseWriter, r *http.Request, params ListResourceReferencesParams)
	// 读取独立控制库权威运行状态
	// (GET /v1/runtime-state)
	ReadRuntimeState(w http.ResponseWriter, r *http.Request)
	// 登记域恢复切换/换回回执
	// (POST /v1/runtime-state/activations)
	RegisterActivation(w http.ResponseWriter, r *http.Request)
	// 按CAS切换epoch与维护阶段
	// (POST /v1/runtime-state:transition)
	TransitionRuntimeState(w http.ResponseWriter, r *http.Request)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(w http.ResponseWriter, r *http.Request, snapshotId Identifier, params ReadSnapshotArchiveParams)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(w http.ResponseWriter, r *http.Request)
	// 导出屏障水位的一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(w http.ResponseWriter, r *http.Request)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(w http.ResponseWriter, r *http.Request)
}

